mapper.select:
SELECT *
FROM target_item
WHERE user_id = #{userId}
  AND DATE_FORMAT(create_time, '%Y-%m-%d') = #{createTime}
ORDER BY create_time DESC

SELECT ti.id,
       t.NAME,
       t.description,
       ti.STATUS,
       ti.create_time
FROM target_item AS ti
         LEFT JOIN target AS t ON t.id = ti.target_id
WHERE
    DATE_FORMAT(ti.create_time, '%Y-%m-%d') = #{createTime}
  AND ti.user_id = #{userId}
ORDER BY ti.create_time DESC LIMIT #{offset}
    , #{limit}

SELECT COUNT(*)
FROM target_item
WHERE user_id = #{userId}
  and DATE_FORMAT(create_time, '%Y-%m-%d') = #{createTime}

SELECT ti.id, t.name, t.description, ti.create_time, ti.status
FROM target t
         left JOIN target_item ti ON ti.target_id = t.id
WHERE ti.user_id = #{userId}
  AND ti.create_time >= #{fromDate}
  AND ti.create_time < #{endDate}
ORDER BY ti.create_time DESC
